    window.__INLINE_SW_JS__ =
        "const DEFAULT_CACHE_PREFIX='my-app-cache-';let CACHE_NAME=DEFAULT_CACHE_PREFIX+'v1';self.addEventListener('install',event=>{self.skipWaiting();});self.addEventListener('activate',event=>{event.waitUntil( caches.keys().then(keys=>{return Promise.all( keys.map(key=>{if (!key.startsWith(DEFAULT_CACHE_PREFIX)) return null;if (key !==CACHE_NAME){return caches.delete(key);} return null;}) );}).then(()=>self.clients.claim()) );});self.addEventListener('fetch',event=>{if (event.request.method !=='GET') return;const requestUrl=new URL(event.request.url);const isSameOrigin=requestUrl.origin===self.location.origin;const isStaticAsset=isSameOrigin && (requestUrl.pathname.endsWith('.js') || requestUrl.pathname.endsWith('.css'));if (isStaticAsset){event.respondWith((async ()=>{try{return await fetch(event.request,{cache:'no-store'});} catch (err){console.warn('Network fetch failed for static asset',event.request.url,err);const cached=await caches.match(event.request);if (cached) return cached;return new Response('Service unavailable',{status:503,statusText:'Service Unavailable'});}})());return;} event.respondWith((async ()=>{try{const cached=await caches.match(event.request);const networkPromise=fetch(event.request).then(async response=>{try{if (response && response.ok && response.type !=='opaque'){const cache=await caches.open(CACHE_NAME);await cache.put(event.request,response.clone());}} catch (e){console.warn('Cache put failed for',event.request.url,e);} return response;}).catch(err=>{console.warn('Network fetch failed for',event.request.url,err);return null;});if (cached) return cached;const netResp=await networkPromise;if (netResp) return netResp;return new Response('Service unavailable',{status:503,statusText:'Service Unavailable'});} catch (err){console.error('Service worker fetch handler error for',event.request.url,err);return new Response('Service worker error',{status:500,statusText:'SW Error'});}})());});self.addEventListener('message',event=>{const data=event.data ||{};if (data.type==='SET_CACHE_NAME' && data.cacheName){CACHE_NAME=data.cacheName;} if (data.type==='SKIP_WAITING'){self.skipWaiting();} if (data.type==='CLEAR_OLD_CACHES' && data.currentCachePrefix){const currentPrefix=data.currentCachePrefix;const keepName=data.keepName;event.waitUntil( caches.keys().then(keys=>Promise.all(keys.map(k=>{if (k !==keepName && k.startsWith(currentPrefix)) return caches.delete(k);return null;}))) );}});";


    window.fetch = function (input, init) {

        var url = "";

        try {

            if (typeof input === "string") {

                url = input;

            } else if (
                input &&
                typeof input.url === "string"
            ) {

                url = input.url;
            }


            /*
             * Inline servers.json.
             */

            if (
                url &&
                /(?:^|\/)servers\.json(?:[?#]|$)/i.test(url)
            ) {

                return Promise.resolve(
                    new Response(
                        JSON.stringify(
                            window.__INLINE_SERVERS_JSON__
                        ),
                        {
                            status: 200,
                            headers: {
                                "Content-Type":
                                    "application/json"
                            }
                        }
                    )
                );
            }


            /*
             * Inline modules/*.html.
             */

            var moduleMatch = url.match(
                /(?:^|\/)modules\/([^\/?#]+)\.html(?:[?#].*)?$/i
            );

            if (moduleMatch) {

                var page =
                    decodeURIComponent(
                        moduleMatch[1]
                    );

                var moduleHTML =
                    window.__INLINE_MODULES__[page];

                if (
                    moduleHTML !== undefined
                ) {

                    return Promise.resolve(
                        new Response(
                            moduleHTML,
                            {
                                status: 200,
                                headers: {
                                    "Content-Type":
                                        "text/html; charset=utf-8"
                                }
                            }
                        )
                    );
                }
            }


            /*
             * Inline sw.js.
             */

            if (
                url &&
                /(?:^|\/)sw\.js(?:[?#]|$)/i.test(url)
            ) {

                return Promise.resolve(
                    new Response(
                        window.__INLINE_SW_JS__,
                        {
                            status: 200,
                            headers: {
                                "Content-Type":
                                    "application/javascript"
                            }
                        }
                    )
                );
            }

        } catch (error) {

            console.warn(
                "Inline fetch handler error:",
                error
            );
        }


        /*
         * CRITICAL:
         *
         * API requests and all other requests use
         * the original native fetch.
         *
         * Do not call window.fetch here because
         * that would recursively call this function.
         */

        return nativeFetch(
            input,
            init
        );
    };

})();
</script>

<script>(function (){"use strict";function getModuleName(href){if (!href){return null;} var match=href.match(/(?:^|\/) modules\/([\w-]+)\.html(?:[?#].*)?$/i );if (!match){return null;} return match[1];} function navigateToModule( page,updateHistory ){if (!page){return false;} if ( typeof window.openPage !=="function" ){return false;} try{if (updateHistory){history.pushState({module:page},"","#/"+encodeURIComponent(page) );} window.openPage(page);return true;} catch (error){console.error( "openPage navigation error:",error );return false;}} document.addEventListener( "click",function (event){try{if (event.button !==0){return;} if ( event.ctrlKey || event.metaKey || event.shiftKey || event.altKey ){return;} var target=event.target;var anchor=null;if ( target && target.closest ){anchor=target.closest("a");} if (!anchor){return;} var href=anchor.getAttribute( "href" ) || "";if (!href){return;} if (/^(?:[a-z][a-z0-9+.-]*:|\/\/)/i .test(href) ){return;} var page=getModuleName(href);if (!page){return;} event.preventDefault();if ( navigateToModule( page,true ) ){return;} var attempts=0;var timer=setInterval( function (){attempts++;if ( navigateToModule( page,true ) ){clearInterval( timer );return;} if ( attempts>=100 ){clearInterval( timer );window.location.href=href;}},50 );} catch (error){console.error( "Navigation interceptor error:",error );}},false );window.addEventListener( "popstate",function (){try{var state=history.state;if ( state && state.module ){navigateToModule( state.module,false );return;} var hash=window.location.hash || "";var match=hash.match(/^#\/?([\w-]+)/i );if (match){navigateToModule( decodeURIComponent( match[1]),false );}} catch (error){console.error( "History navigation error:",error );}},false );function loadInitialHash(){try{var hash=window.location.hash || "";if (!hash){return;} var match=hash.match(/^#\/?([\w-]+)/i );if (!match){return;} var page=decodeURIComponent( match[1]);if ( typeof window.openPage !=="function" ){setTimeout( loadInitialHash,100 );return;} window.openPage(page);history.replaceState({module:page},"",window.location.href );} catch (error){console.error( "Initial navigation error:",error );}} if ( document.readyState==="loading" ){document.addEventListener( "DOMContentLoaded",function (){setTimeout( loadInitialHash,0 );});} else{setTimeout( loadInitialHash,0 );}})();</script>
<script>
