e;showProgress('Notifying service worker (if present)...');if ('serviceWorker' in navigator && navigator.serviceWorker.controller){shouldDelayReload=true;try{navigator.serviceWorker.controller.postMessage({type:'SET_CACHE_NAME',cacheName:newCacheName});navigator.serviceWorker.controller.postMessage({type:'CLEAR_OLD_CACHES',currentCachePrefix:CACHE_PREFIX,keepName:newCacheName});navigator.serviceWorker.controller.postMessage({type:'SKIP_WAITING'});} catch (e){console.warn('Messaging service worker failed',e);}} showProgress('Clearing CacheStorage...');await clearCaches();showProgress('Unregistering service workers...');await unregisterServiceWorkers();showProgress('Removing IndexedDB databases...');await clearIndexedDB();showProgress('Clearing cookies...');clearCookies();showProgress('Requesting server logout...');try{await fetch(resolveApiUrl('/auth/logout'),{method:'POST',credentials:'include'});console.log('Requested server logout (clear HttpOnly cookies)');} catch (e){console.warn('logout request failed',e);} showProgress('Finalizing and reloading...');showToast('Local data cleared — reloading','success',2500);try{if (serverVersion){localStorage.setItem('cacheVersion',serverVersion);}} catch (e){} if (shouldDelayReload){setTimeout(()=>window.location.reload(true),600);} else{window.location.reload(true);}} checkAndUpdate();window.checkForNewVersion=checkAndUpdate;window.forceUpdateApp=forceUpdateApp;})();
