const app=document.getElementById("app");const STORAGE_KEY="pat_user";const APP_MAX_WIDTH=430;function syncAppScale(){const scale=Math.min(1,window.innerWidth/APP_MAX_WIDTH);document.documentElement.style.setProperty("--app-scale",scale.toFixed(3));document.documentElement.style.setProperty("--app-zoom",scale.toFixed(3));} window.addEventListener("resize",syncAppScale);window.addEventListener("orientationchange",syncAppScale);syncAppScale();const SERVERS_JSON_URL=new URL('./servers.json',window.location.href).toString();let apiServers=[];let activeApiBase=null;window.__PAT_API_SERVERS__=apiServers;window.__PAT_ACTIVE_API_BASE__=activeApiBase;function normalizeBase(b){try{return String(b || "").trim().replace(/\/+$/,"")+"/";} catch (e){return null;}} function lockInApiBase(base){const clean=normalizeBase(base);if (!clean) return;activeApiBase=clean;const unique=[clean].concat((apiServers ||[]).filter(item=>normalizeBase(item) !==clean));apiServers=unique.filter(Boolean);window.__PAT_API_SERVERS__=apiServers;window.__PAT_ACTIVE_API_BASE__=activeApiBase;} async function loadApiServers(){const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),5000);const u=new URL(SERVERS_JSON_URL);u.searchParams.set('_ts',String(Date.now()));const res=await fetch(u.toString(),{cache:'no-store',signal:controller.signal});clearTimeout(timeout);if (!res.ok) throw new Error('Failed to fetch servers.json:'+res.status);const j=await res.json();let rawList=[];if (Array.isArray(j) && j.length>0){rawList=j.slice();} else if (j && Array.isArray(j.servers) && j.servers.length>0){rawList=j.servers .map(s=>{return{url:(s && s.url) ? String(s.url):'',priority:(s && typeof s.priority !=='undefined') ? Number(s.priority):9999};}) .filter(item=>item.url) .sort((a,b)=>(a.priority || 9999)-(b.priority || 9999)) .map(item=>item.url);} apiServers=rawList.map(normalizeBase).filter(Boolean);if (activeApiBase && apiServers.includes(activeApiBase)){lockInApiBase(activeApiBase);} 