verview","v1/account/summary":"v1/account/summary","v1/network/summary":"v1/network/summary","v1/market/status":"v1/market/status","v1/activity/report":"v1/activity/report","v1/lockins/create":"v1/lockins/create","v1/payments/create":"v1/payments/create"};if (routeMap[cleaned]){return routeMap[cleaned];} if (cleaned.startsWith("v1/")){return cleaned;} return cleaned;} function resolveApiUrl(url){const normalized=normalizeApiRoute(url);const base=getPrimaryBase();return new URL(normalized,base).toString();} async function waitForServers(timeoutMs=5000){if (apiServers && apiServers.length) return true;const start=Date.now();return new Promise(resolve=>{const interval=100;const id=setInterval(()=>{if (apiServers && apiServers.length){clearInterval(id);resolve(true);return;} if (Date.now()-start>=timeoutMs){clearInterval(id);resolve(false);}},interval);});} let aiStatusInterval=null;let tradeSettings={yieldPercent:6,durationDays:25};let tradePageState={availableBalance:0};function getCurrentUser(){try{return JSON.parse(localStorage.getItem(STORAGE_KEY) || "null");} catch (error){return null;}} function formatCurrency(value){const number=Number(value || 0);if (number>=1000000){return "₱"+(number/1000000).toFixed(1)+"M";} if (number>=1000){return "₱"+(number/1000).toFixed(1)+"K";} return "₱"+number.toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2});} function formatCurrencyFull(value){const number=Number(value || 0);return "₱"+number.toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2});} function formatPercent(value){return Number(value || 0).toFixed(2)+"%";} function getAdjustedNumericId(id,offset=2608){const n=Number(id || 0);if (isNaN(n)) return offset;return n+offset;} function formatTradeLabelFromString(label,offset=2608){if (!label) return 'Trade payout';if (typeof label !=='string') return String(label);const s=label.trim();if (!s.startsWith('Trade #')) return s || 'Trade payout';const m=s.match(/\d+/);if (m && m[0]){return 'Trade #'+(Number(m[0])+offset);} return s;} function formatLockinDisplayLabel(label,offset=8026){if (!label) return 'Lock-in payout';if (typeof label !=='string') return String(label);let out=label.trim();out=out.replace(/\(id\s*(\d+)\)/ig,(_,value)=>'(id '+(Number(value)+offset)+')');return out || 'Lock-in payout';} function sanitizeReferralNote(note,type){let out=String(note || '');if (type==='referral'){out=out.replace(/\s*•\s*Investment\s*#?\s*\d+/ig,'');out=out.replace(/\s*\+\s*2608/ig,'');out=out.replace(/\binvestment\s*#?\s*\d+\b/ig,'');out=out.replace(/\s{2,}/g,' ').trim();if (!out) out='Referral bonus';} return out;} function handleSessionExpired(message="Session expired. Please log in again."){const normalized=String(message || "").toLowerCase();const isAuthFailure=normalized.includes("please log in first") || normalized.includes("session expired") || normalized.includes("sign-in required") || normalized.includes("admin sign-in required") || normalized.includes("invalid csrf") || normalized.includes("unauthorized");if (!isAuthFailure){return false;} if (window.__patSessionExpiredHandled){return true;} window.__patSessionExpiredHandled=true;try{localStorage.removeItem("pat_user");} catch (e){} try{localStorage.removeItem("pat_username");} catch (e){} try{sessionStorage.clear();} catch (e){} try{fetch(resolveApiUrl("logout.php"),{method:"POST",credentials:"include",headers:{"Content-Type":"application/json"}}).catch(()=>{});} catch (e){} showToast(message || "Session expired. Please log in again.","error");setTimeout(()=>{openPage("login");},700);return true;} async function requestJson(url,payload=null,method="POST"){const baseOptions={method,credentials:"include",headers:{"Content-Type":"application/json"}};if (payload !==null){baseOptions.body=JSON.stringify(payload);} const serversReady=await waitForServers(5000);if (!serversReady){console.error('requestJson:no API servers configured (servers.json not loaded or empty)');return{success:false,message:'No API servers configured.'};} const candidates=apiServers.slice();for (let i=0;i<candidates.length;i++){const base=candidates[i];const normalizedUrl=normalizeApiRoute(url);const fullUrl=new URL(normalizedUrl,base);if (method && String(method).toUpperCase()==='GET'){fullUrl.searchParams.set('_ts',String(Date.now()));} const finalUrl=fullUrl.toString();let timeoutId=null;try{const opts=Object.assign({},baseOptions,{cache:'no-store'});const controller=new AbortController();timeoutId=setTimeout(()=>controller.abort(),5000);opts.signal=controller.signal;const response=await fetch(finalUrl,opts);clearTimeout(timeoutId);if (response.ok){lockInApiBase(base);} let data={};try{const text=await response.text();if (text) data=JSON.parse(text);} catch (error){console.error("Invalid JSON response from "+finalUrl,error);data={success:false,message:"Request failed."};} if (response.status===401 || response.status===403){handleSessionExpired(data.message || "Session expired. Please log in again.");return data;} if (response.status>=500){console.warn('Server reported HTTP '+response.status+' for '+fullUrl+',trying next server if any.');continue;} if (response.status>=400 && response.status<500){return data;} if (data && typeof data.success !=='undefined' && data.success===false){const message=String(data.message || "");if (message.toLowerCase().includes("please log in first") || message.toLowerCase().includes("session expired") || message.toLowerCase().includes("sign-in required") || message.toLowerCase().includes("admin sign-in required")){handleSessionExpired(message);} return data;} return data;} catch (err){if (timeoutId) clearTimeout(timeoutId);console.warn('Request to '+fullUrl+' failed,trying next server if any.',err);continue;}} console.error("requestJson:all API servers failed for "+url);return{success:false,message:"Request failed."};} function openPage(page,element){const bottomNav=document.getElementById("bottomNav");if (page==="login" || page==="register"){if (bottomNav) bottomNav.style.display="none";} else{if (bottomNav) bottomNav.style.display="flex";document.querySelectorAll(".nav").forEach(nav=>{nav.classList.remove("active");});const matchingNav=document.querySelector(`.nav[data-page="${page}"]`);if (matchingNav){matchingNav.classList.add("active");} else if (element){element.classList.add("active");}} try{if (app){app.innerHTML='<div class="page-loading" aria-hidden="true"><div class="spinner" aria-hidden="true"></div></div>';} try{window.scrollTo({top:0,left:0,behavior:'auto'});} catch (e){document.documentElement.scrollTop=0;}} catch (e){} fetch("./modules/"+page+".html") .then(response=>{if (!response.ok) throw new Error("Module not found");return response.text();}) .then(data=>{if (app) app.innerHTML='<div class="page-wrapper" style="display:none">'+data+'</div>';try{window.scrollTo({top:0,left:0,behavior:'auto'});} catch (e){document.documentElement.scrollTop=0;} const initResult=initializePage(page);Promise.resolve(initResult) .then(()=>{const wrapper=app ? app.querySelector('.page-wrapper'):null;if (wrapper){wrapper.style.display='block';void wrapper.offsetWidth;wrapper.classList.add('page-visible');}}) .catch(err=>{console.error('Page initialization error',err);const wrapper=app ? app.querySelector('.page-wrapper'):null;if (wrapper){wrapper.style.display='block';void wrapper.offsetWidth;wrapper.classList.add('page-visible');}});}) .catch(error=>{console.error(error);if (app){app.innerHTML=`<div class="page-error"><h2>Page not found</h2><div class="subtitle">Unable to load page.</div><div style="margin-top:12px;"><button class="btn" onclick="openPage('${page}')">Retry</button></div></div>`;}});} function initializePage(page){if (aiStatusInterval){clearInterval(aiStatusInterval);aiStatusInterval=null;} document.querySelectorAll(".card").forEach(card=>{card.addEventListener("touchstart",()=>{card.style.transform="scale(.98)";});card.addEventListener("touchend",()=>{card.style.transform="scale(1)";});});const initPromis