drawStatusEl.style.color=isActive ? 'var(--primary)':'var(--danger)';} const withdrawButtonEl=document.getElementById("withdrawButton");if (withdrawButtonEl){withdrawButtonEl.disabled=!(data.user && data.user.is_active);withdrawButtonEl.style.opacity=(data.user && data.user.is_active) ? '1':'0.6';} const withdrawMode=document.getElementById("withdrawMode");if (withdrawMode){withdrawMode.addEventListener('change',updateWithdrawModeHint);withdrawMode.addEventListener('change',saveWithdrawalInfo);} updateWithdrawModeHint();const fullNameInput=document.getElementById("withdrawFullName");if (fullNameInput){fullNameInput.addEventListener('change',saveWithdrawalInfo);} const accountNumberInput=document.getElementById("withdrawAccountNumber");if (accountNumberInput){accountNumberInput.addEventListener('change',saveWithdrawalInfo);} const saveCheckbox=document.getElementById("saveWithdrawalInfo");if (saveCheckbox){saveCheckbox.addEventListener('change',saveWithdrawalInfo);} loadSavedWithdrawalInfo();const tradeEl=document.getElementById("walletTradeValue");if (tradeEl){tradeEl.textContent=formatCurrency(Number(wallet.invested_balance || 0));} const profitEl=document.getElementById("walletProfitValue");if (profitEl){profitEl.textContent=formatCurrency(Number(wallet.profit_balance || 0));} const bonusEl=document.getElementById("walletBonusValue");if (bonusEl){const bonusTotal=Number(wallet.referral_balance || 0)+Number(wallet.leadership_balance || 0);bonusEl.textContent=formatCurrency(bonusTotal);} const profitListEl=document.getElementById("profitHistoryList");if (profitListEl){if (!profitHistory.length){profitListEl.innerHTML='<div class="row"><span>No profit history yet</span></div>';} else{profitListEl.innerHTML=profitHistory.map(item=>{const amountText='+'+formatCurrency(Number(item.amount || 0));const label=item.description ? formatLockinDisplayLabel(item.description,8026):'Daily profit';let tradeLabel=item.trade_label && String(item.trade_label).toLowerCase().includes('lock-in') ? 'Lock-in payout':formatTradeLabelFromString(item.trade_label);const dateText=item.created_at ? new Date(String(item.created_at).replace(' ','T')).toLocaleString('en-US',{timeZone:'Asia/Manila',month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit',hour12:true}):'';return `<div class="row" style="align-items:flex-start;gap:8px;"><div style="display:flex;flex-direction:column;gap:2px;min-width:0;"><span style="font-size:0.9rem;">${label}</span><small style="color:#666;">${tradeLabel}</small>${dateText ? `<small style="color:#666;">${dateText}</small>`:''}</div><strong style="color:var(--primary);white-space:nowrap;">${amountText}</strong></div>`;}).join('');}} const bonusListEl=document.getElementById("bonusHistoryList");if (bonusListEl){if (!bonusHistory.length){bonusListEl.innerHTML='<div class="row"><span>No bonus history yet</span></div>';} else{bonusListEl.innerHTML=bonusHistory.map(item=>{const amountText='+'+formatCurrency(Number(item.amount || 0));const label=item.label || (item.type==='leadership' ? 'Leadership bonus':'Referral bonus');let note=sanitizeReferralNote(item.description || 'Bonus payout',item.type);const dateText=item.created_at ? new Date(String(item.created_at).replace(' ','T')).toLocaleString('en-US',{timeZone:'Asia/Manila',month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit',hour12:true}):'';return `<div class="row" style="align-items:flex-start;gap:8px;"><div style="display:flex;flex-direction:column;gap:2px;min-width:0;"><span style="font-size:0.9rem;">${label}</span><small style="color:#666;">${note}</small>${dateText ? `<small style="color:#666;">${dateText}</small>`:''}</div><strong style="color:var(--primary);white-space:nowrap;">${amountText}</strong></div>`;}).join('');}} const listEl=document.getElementById("transactionList");if (listEl){if (!transactions.length){listEl.innerHTML='<div class="row"><span>No transactions yet</span></div>';} else{listEl.innerHTML=transactions.map(txn=>{const isCredit=txn.type==='deposit' || txn.type==='bonus';const amountText=(isCredit ? '+':'-')+formatCurrency(Number(txn.amount || 0));const color=isCredit ? 'var(--primary)':'var(--danger)';const statusText=txn.status ? ` • ${txn.status.toUpperCase()}`:'';const label=txn.type==='deposit' ? 'Deposit':txn.type==='withdrawal' ? 'Withdrawal':(txn.label || txn.type || 'Transaction');const dateValue=txn.created_at || txn.date || txn.timestamp || txn.transaction_date;const dateText=dateValue ? new Date(String(dateValue).replace(' ','T')).toLocaleString('en-US',{timeZone:'Asia/Manila',month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit',hour12:true}):'';return `<div class="row" style="align-items:flex-start;gap:8px;"><div style="display:flex;flex-direction:column;gap:2px;min-width:0;"><span style="font-size:0.9rem;">${label} ${statusText}</span>${dateText ? `<small style="color:#666;">${dateText}</small>`:''}</div><strong style="color:${color};white-space:nowrap;">${amountText}</strong></div>`;}).join('');}}});} function updateWithdrawModeHint(){const withdrawMode=document.getElementById("withdrawMode");const hint=document.getElementById("withdrawModeHint");if (!withdrawMode || !hint) return;if (["gcash","paymaya","gotyme"].includes(withdrawMode.value)){hint.textContent="Selected payout mode is processed instantly.";} else{hint.textContent="Bank transfers create a withdrawal request for manual processing.";}} function loadSavedWithdrawalInfo(){try{const saved=JSON.parse(localStorage.getItem("pat_withdrawal_info") || "null");if (!saved) return;const modeInput=document.getElementById("withdrawMode");const fullNameInput=document.getElementById("withdrawFullName");const accountNumberInput=document.getElementById("withdrawAccountNumber");const saveCheckbox=document.getElementById("saveWithdrawalInfo");if (modeInput && saved.mode) modeInput.value=saved.mode;if (fullNameInput && saved.fullName) fullNameInput.value=saved.fullName;if (accountNumberInput && saved.accountNumber) accountNumberInput.value=saved.accountNumber;if (saveCheckbox) saveCheckbox.checked=true;updateWithdrawModeHint();} catch (e){}} function saveWithdrawalInfo(){const saveCheckbox=document.getElementById("saveWithdrawalInfo");if (!saveCheckbox || !saveCheckbox.checked){localStorage.removeItem("pat_withdrawal_info");return;} const modeInput=document.getElementById("withdrawMode");const fullNameInput=document.getElementById("withdrawFullName");const accountNumberInput=document.getElementById("withdrawAccountNumber");const withdrawalInfo={mode:modeInput ? modeInput.value:"gcash",fullName:fullNameInput ? fullNameInput.value.trim():"",accountNumber:accountNumberInput ? accountNumberInput.value.trim():"",};localStorage.setItem("pat_withdrawal_info",JSON.stringify(withdrawalInfo));} function resetWithdrawStatus(){const withdrawStatusEl=document.getElementById("withdrawStatus");if (withdrawStatusEl){withdrawStatusEl.textContent='';withdrawStatusEl.style.color='var(--primary)';}} const WITHDRAWAL_REQUEST_COOLDOWN_MS=4000;let withdrawalRequestLockUntil=0;let withdrawalRequestInFlight=false;function getWithdrawalFee(){return 10;} function isWithdrawalRequestLocked(){const remaining=Math.max(0,withdrawalRequestLockUntil-Date.now());return withdrawalRequestInFlight || remaining>0;} function setWithdrawalCooldown(){withdrawalRequestInFlight=true;withdrawalRequestLockUntil=Date.now()+WITHDRAWAL_REQUEST_COOLDOWN_MS;const withdrawButton=document.getElementById("withdrawButton");if (withdrawButton){withdrawButton.disabled=true;withdrawButton.style.opacity='0.6';}} function clearWithdrawalCooldown(){withdrawalRequestInFlight=false;withdrawalRequestLockUntil=0;const withdrawButton=document.getElementById("withdrawButton");if (withdrawButton){const user=getCurrentUser();const active=Boolean(user && user.id);withdrawButton.disabled=!active;withdrawButton.style.opacity=active ? '1':'0.6';}} function showWithdrawalConfirmation(){const user=JSON.parse(localStorage.getItem("pat_user") || "null");const amountInput=document.getElementById("withdrawAmount");const modeInput=document.getElementById("withdrawMode");const fullNameInput=document.getElementById("withdrawFullName");const accountNumberInput=document.getElementById("withdrawAccountNumber");const amount=Number(amountInput ? amountInput.value:0);const mode=modeInput ? modeInput.value:"gcash";const fullName=fullNameInput ? fullNameInput.value.trim():"";const accountNumber=accountNumberInput ? accountNumberInput.value.trim():"";if (!user || !user.id){showToast("Please log in first","error");return;} if (!amount || amount<200){showToast("Minimum withdrawal amount is ₱200","error");return;} if (!fullName){showToast("Please enter your full name","error");return;} if (!accountNumber){showToast("Please enter your account number","error");return;} const fee=getWithdrawalFee();const netPayout=Math.max(amount-fee,0);const existingModal=document.getElementById("withdrawalConfirmationModal");if (existingModal) existingModal.remove();const overlay=document.createElement('div');overlay.id='withdrawalConfirmationModal';overlay.style.position='fixed';overlay.style.inset='0';overlay.style.background='rgba(0,0,0,0.72)';overlay.style.display='flex';overlay.style.alignItems='center';overlay.style.justifyContent='center';overlay.style.zIndex='99999';overlay.style.padding='16px';const box=document.createElement('div');box.style.background='#fff';box.style.width='min(520px,100%)';box.style.borderRadius='16px';box.style.padding='24px';box.style.boxShadow='0 20px 70px rgba(0,0,0,0.22)';const title=document.createElement('h3');title.textContent='Confirm Withdrawal';title.style.margin='0 0 10px';box.appendChild(title);const subtitle=document.createElement('div');subtitle.textContent='Please review the payout details before sending the request.';subtitle.style.color='#666';subtitle.style.fontSize='13px';subtitle.style.marginBottom='12px';box.appendChild(subtitle);const details=document.createElement('div');details.style.border='1px solid #eee';details.style.borderRadius='10px';details.style.padding='12px';details.style.background='#fafafa';const rows=[['Requested amount',formatCurrency(Number(amount))],['Payment method',(modeInput ? modeInput.options && modeInput.options[modeInput.selectedIndex]:null)?.text || String(mode).toUpperCase() || 'GCash'],['Full name',fullName],['Account number',accountNumber],['Transaction fee','-'+formatCurrency(fee)],['Total',formatCurrency(netPayout)]];rows.forEach(([label,value])=>{const row=document.createElement('div');row.style.display='flex';row.style.justifyContent='space-between';row.style.alignItems='center';row.style.gap='12px';row.style.padding='7px 0';row.style.borderBottom='1px solid #eee';if (rows.indexOf([label,value])===rows.length-1){row.style.borderBottom='none';} const labelEl=document.createElement('span');labelEl.textContent=label;labelEl.style.fontSize='12px';labelEl.style.color='#666';const valueEl=document.createElement('strong');valueEl.textContent=value;valueEl.style.fontSize='13px';valueEl.style.color='#111';if (label==='Transaction fee'){valueEl.style.color='#d9534f';} row.appendChild(labelEl);row.appendChild(valueEl);details.appendChild(row);});box.appendChild(details);const note=document.createElement('div');note.style.marginTop='12px';note.style.fontSize='11px';note.style.color='#777';note.textContent='Net payout=requested amount minus transaction fee.';box.appendChild(note);const actions=document.createElement('div');actions.style.marginTop='18px';actions.style.display='flex';actions.style.justifyContent='flex-end';actions.style.gap='10px';const cancel=document.createElement('button');cancel.type='button';cancel.textContent='Cancel';cancel.className='btn btn-secondary';cancel.style.padding='10px 14px';cancel.onclick=()=>overlay.remove();const submit=document.createElement('button');submit.type='button';submit.textContent='Confirm Request';submit.className='btn';submit.style.padding='10px 14px';submit.onclick=()=>{overlay.remove();requestWalletWithdrawal(user.id,amount,mode,fullName,accountNumber);};actions.appendChild(cancel);actions.appendChild(submit);box.appendChild(actions);overlay.appendChild(box);document.body.appendChild(overlay);} function requestWalletWithdrawal(userId=null,amount=null,mode=null,fullName=null,accountNumber=null){const user=JSON.parse(localStorage.getItem("pat_user") || "null");const amountInput=document.getElementById("withdrawAmount");const modeInput=document.getElementById("withdrawMode");const fullNameInput=document.getElementById("withdrawFullName");const accountNumberInput=document.getElementById("withdrawAccountNumber");const resolvedUserId=userId || (user ? user.id:null);const resolvedAmount=Number(amount ?? (amountInput ? amountInput.value:0));const resolvedMode=mode || (modeInput ? modeInput.value:"gcash");const resolvedFullName=String(fullName || (fullNameInput ? fullNameInput.value.trim():""));const resolvedAccountNumber=String(accountNumber || (accountNumberInput ? accountNumberInput.value.trim():""));if (!resolvedUserId){showToast("Please log in first","error");return;} if (isWithdrawalRequestLocked()){const remainingSeconds=Math.max(1,Math.ceil((withdrawalRequestLockUntil-Date.now())/1000));showToast(`Please wait ${remainingSeconds} s before submitting another withdrawal request.`,"error");return;} if (!resolvedAmount || resolvedAmount<200){showToast("Minimum withdrawal amount is ₱200","error");return;} if (!resolvedFullName){showToast("Please enter your full name","error");return;} if (!resolvedAccountNumber){showToast("Please enter your account number","error");return;} setWithdrawalCooldown();const withdrawStatusEl=document.getElementById("withdrawStatus");if (withdrawStatusEl){withdrawStatusEl.textContent='Processing...';withdrawStatusEl.style.color='var(--primary)';} requestJson("wallet.php",{action:'request_withdrawal',amount:resolvedAmount,mode:resolvedMode,full_name:resolvedFullName,account_number:resolvedAccountNumber}) .then(data=>{showToast(data.message || "Withdrawal request submitted",data.success ? "success":"error");if (data.success){saveWithdrawalInfo();if (amountInput) amountInput.value="";loadWalletData();} else{resetWithdrawStatus();}}) .catch(()=>{resetWithdrawStatus();}) .finally(()=>{clearWithdrawalCooldown();});} function openWithdrawalConfirmationModal(){showWithdrawalConfirmation();} window.onload=()=>{const bottomNav=document.getElementById("bottomNav");if (bottomNav) bottomNav.style.display="none";const params=new URLSearchParams(window.location.search);const tradeResult=params.get("trade");const lockinResult=params.get("lockin");if (tradeResult==="success"){showToast("Trade payment completed. Your investment will activate once payment is confirmed.","success");} else if (tradeResult==="cancel"){showToast("Trade payment was cancelled.","error");} if (lockinResult==="success"){showToast("Lock-in payment completed. Your lock-in will activate once payment is confirmed.","success");} else if (lockinResult==="cancel"){showToast("Lock-in payment was cancelled.","error");} if (tradeResult){params.delete("trade");} if (lockinResult){params.delete("lockin");} const newSearch=params.toString();if (tradeResult || lockinResult){history.replaceState(null,"",window.location.pathname+(newSearch ? `?${newSearch}`:""));} const savedUser=JSON.parse(localStorage.getItem("pat_user") || "null");const referralCode=params.get("ref");if (referralCode && (!savedUser || !savedUser.id)){openPage("register");} else if (savedUser && savedUser.id){openPage("home");} else{openPage("login");}};
</script>
<script>(function(){function reveal(){document.body.classList.remove('app-not-ready');var el=document.getElementById('loading-overlay');if(el)el.parentNode.removeChild(el);}var attempts=0;function check(){attempts++;if(typeof window.openPage==='function' || attempts>=200){reveal();}else{setTimeout(check,50)}}if(document.readyState==='complete'){check();}else{window.addEventListener('DOMContentLoaded',check);}})();</script>

</body>
</html>
